def test_trie_search(words: list[str], prefix: str) -> bool:
    root = {}
    for word in words:
        cur = root
        for ch in word:
            cur = cur.setdefault(ch, {})
    cur = root
    for ch in prefix:
        if ch not in cur:
            return False
        cur = cur[ch]
    return True

def simulate_lru_cache(capacity: int, operations: list[dict]) -> list:
    from collections import OrderedDict
    cache = OrderedDict()
    out = []
    for op in operations:
        if op['op'] == 'put':
            k, v = op['k'], op['v']
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op['op'] == 'get':
            k = op['k']
            if k in cache:
                cache.move_to_end(k)
                out.append(cache[k])
            else:
                out.append(-1)
    return out

def sliding_window_rate_limiter(timestamps: list[int], now: int, max_req: int, window: int) -> bool:
    active = [t for t in timestamps if now - window <= t <= now]
    return len(active) < max_req

def eval_rpn(tokens: list[str]) -> int:
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+': stack.append(a + b)
            elif t == '-': stack.append(a - b)
            elif t == '*': stack.append(a * b)
            elif t == '/': stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[0]

def simulate_traffic_light(steps: int) -> str:
    states = ['Green', 'Yellow', 'Red']
    return states[steps % 3]

def bfs_shortest_path(graph: dict, start: str, target: str) -> list[str]:
    from collections import deque
    if start == target:
        return [start]
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                new_path = path + [neighbor]
                if neighbor == target:
                    return new_path
                queue.append(new_path)
    return []

def has_overlapping_intervals(intervals: list[list[int]]) -> bool:
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    for i in range(len(sorted_intervals) - 1):
        if sorted_intervals[i][1] > sorted_intervals[i+1][0]:
            return True
    return False

def schedule_priority_tasks(tasks: list[dict]) -> list[str]:
    sorted_tasks = sorted(tasks, key=lambda t: (-t['priority'], t['name']))
    return [t['name'] for t in sorted_tasks]

def python_master_evaluator(commands: list[str]) -> dict[str, int]:
    memory = {}
    for cmd in commands:
        parts = cmd.split()
        if len(parts) == 3:
            var, op, val_str = parts
            val = int(val_str)
            if op == '=':
                memory[var] = val
            elif op == '+=':
                memory[var] = memory.get(var, 0) + val
            elif op == '-=':
                memory[var] = memory.get(var, 0) - val
    return {k: memory[k] for k in sorted(memory.keys())}
